package cue

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerror "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
	yamlv3 "gopkg.in/yaml.v3"
)

const (
	jsonFormat = "json"
	textFormat = "text"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// ValidateBytes takes a slice of bytes, and validates them against a cue definition.
func ValidateBytes(b []byte) error {
	cctx := cuecontext.New()

	return validate(b, cctx)
}

func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)

	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}

	yv := cctx.BuildFile(f, cue.Scope(v))
	yv = v.Unify(yv)

	return yv.Validate()
}

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result contains every issue found while validating a document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator holds the compiled features schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, err
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// sourceLocation walks the original YAML tree, including sequence indices. A
// missing field has no node of its own, so its nearest existing parent is used.
func sourceLocation(root *yamlv3.Node, path []string, key bool) (int, int) {
	n := root
	if n.Kind == yamlv3.DocumentNode && len(n.Content) > 0 {
		n = n.Content[0]
	}
	var label *yamlv3.Node
	for _, part := range path {
		switch n.Kind {
		case yamlv3.MappingNode:
			found := false
			for i := 0; i+1 < len(n.Content); i += 2 {
				if n.Content[i].Value == part {
					label, n, found = n.Content[i], n.Content[i+1], true
					break
				}
			}
			if !found {
				return n.Line, n.Column
			}
		case yamlv3.SequenceNode:
			i, err := strconv.Atoi(part)
			if err != nil || i < 0 || i >= len(n.Content) {
				return n.Line, n.Column
			}
			n = n.Content[i]
			label = nil
		default:
			return n.Line, n.Column
		}
	}
	if key && label != nil {
		return label.Line, label.Column
	}
	return n.Line, n.Column
}

// Validate checks YAML content and returns all schema errors with source locations.
func (fv *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: []Error{}}
	f, err := yaml.Extract(file, b)
	if err != nil {
		return result, fmt.Errorf("%w: %v", ErrValidationFailed, err)
	}
	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil {
		return result, fmt.Errorf("%w: %v", ErrValidationFailed, err)
	}
	yv := fv.v.Unify(fv.cue.BuildFile(f, cue.Scope(fv.v)))
	if err := yv.Validate(); err != nil {
		for _, ce := range cueerror.Errors(err) {
			path := ce.Path()
			message, args := ce.Msg()
			message = fmt.Sprintf(message, args...)
			line, column := sourceLocation(&root, path, strings.Contains(message, "field not allowed"))
			result.Errors = append(result.Errors, Error{
				Path: strings.Join(path, "."), Message: message,
				Location: Location{File: file, Line: line, Column: column},
			})
		}
		return result, ErrValidationFailed
	}
	return result, nil
}

func writeErrorDetails(format string, cerrs []Error, w io.Writer) error {
	var sb strings.Builder

	buildErrorMessage := func() {
		sb.WriteString("❌ Validation failure!\n\n")

		for i := 0; i < len(cerrs); i++ {
			errString := fmt.Sprintf(`
- Field  : %s
  Message: %s
  File   : %s
  Line   : %d
  Column : %d
`, cerrs[i].Path, cerrs[i].Message, cerrs[i].Location.File, cerrs[i].Location.Line, cerrs[i].Location.Column)

			sb.WriteString(errString)
		}
	}

	switch format {
	case jsonFormat:
		if err := json.NewEncoder(w).Encode(Result{Errors: cerrs}); err != nil {
			fmt.Fprintln(w, "Internal error.")
			return err
		}

		return nil
	case textFormat:
		buildErrorMessage()
	default:
		sb.WriteString("Invalid format chosen, defaulting to \"text\" format...\n")
		buildErrorMessage()
	}

	fmt.Fprint(w, sb.String())

	return nil
}

// ValidateFiles takes a slice of strings as filenames and validates them against
// our cue definition of features.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	fv, err := NewFeaturesValidator()
	if err != nil {
		return err
	}

	cerrs := make([]Error, 0)

	for _, f := range files {
		b, err := os.ReadFile(f)
		// Quit execution of the cue validating against the yaml
		// files upon failure to read file.
		if err != nil {
			return fmt.Errorf("%w: failed to read %s: %v", ErrValidationFailed, f, err)
		}
		result, err := fv.Validate(f, b)
		cerrs = append(cerrs, result.Errors...)
		if err != nil && !errors.Is(err, ErrValidationFailed) {
			return err
		}
	}

	if len(cerrs) > 0 {
		if err := writeErrorDetails(format, cerrs, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	// JSON output always contains a structured result.
	if format == jsonFormat {
		return writeErrorDetails(format, cerrs, dst)
	}

	if format != textFormat {
		fmt.Fprint(dst, "Invalid format chosen, defaulting to \"text\" format...\n")
	}

	fmt.Fprintln(dst, "✅ Validation success!")

	return nil
}
